import{_ as t,o as e,c as o,a6 as c}from"./chunks/framework.BrkgobfX.js";const p=JSON.parse('{"title":"斜杠命令","description":"交互会话中的全部斜杠命令（按用途分组），常用快捷键与输入技巧，以及全屏对话记录的操作","frontmatter":{"title":"斜杠命令","description":"交互会话中的全部斜杠命令（按用途分组），常用快捷键与输入技巧，以及全屏对话记录的操作","source":"https://daiw.org/manual/codex/slash-commands"},"headers":[],"relativePath":"manual/agent/codex/slash-commands.md","filePath":"manual/agent/codex/slash-commands.md"}'),r={name:"manual/agent/codex/slash-commands.md"};function a(l,d,n,i,s,h){return e(),o("div",null,[...d[0]||(d[0]=[c('<h1 id="斜杠命令" tabindex="-1">斜杠命令 <a class="header-anchor" href="#斜杠命令" aria-label="Permalink to &quot;斜杠命令&quot;">​</a></h1><blockquote><p>交互会话中的全部斜杠命令（按用途分组），常用快捷键与输入技巧，以及全屏对话记录的操作</p></blockquote><p>在输入框<strong>开头</strong>输入 <code>/</code> 会弹出命令菜单（v0.162.0 起在 Vim 普通模式下输入框为空时按 <code>/</code> 同样会打开），继续输入会按命令名的前缀筛选（不分大小写，与输入完全相同的命令排在首位）；支持参数的命令把参数写在同一行，例如 <code>/review 只看权限相关的改动</code>。本页已核对至 Codex CLI v0.167.0；CLI 文档没有列出的命令会在备注中注明。</p><p>Codex 正在工作时，输入斜杠命令后按 <code>Tab</code> 可以把它排到下一轮执行。排队的命令在真正执行时才解析，所以菜单和报错会在当前这一轮结束后才出现。</p><h2 id="模型与模式" tabindex="-1">模型与模式 <a class="header-anchor" href="#模型与模式" aria-label="Permalink to &quot;模型与模式&quot;">​</a></h2><table tabindex="0"><thead><tr><th>命令</th><th>作用</th><th>参数</th><th>备注</th></tr></thead><tbody><tr><td><code>/model</code></td><td>选择模型与推理强度</td><td>可选，行内指定模型、推理强度与速度（v0.164.0 起）</td><td>选择器里按 <code>Enter</code> 保存为默认值，按 <code>s</code> 只用于当前会话（v0.156.0 起）</td></tr><tr><td><code>/presets</code></td><td>运行或保存可复用的提示词与斜杠命令</td><td></td><td>v0.164.0 新增；支持 10 个编号槽位（<code>0</code>–<code>9</code>，保存在 <code>tui.presets</code>），可通过快捷键菜单快速调用；不支持 <code>!</code> 开头的 shell 命令</td></tr><tr><td><code>/daybreak</code></td><td>开启或关闭 Daybreak 网络安全访问模式</td><td></td><td>v0.161.0 新增；需启用 <code>features.cli_daybreak</code>（v0.163.0 起符合条件的账号默认开启），开启后状态栏与终端标题显示指示器</td></tr><tr><td><code>/fast</code></td><td>开关当前模型的 Fast 服务档位，并记住选择</td><td></td><td>只有模型目录为当前模型提供该档位时才出现，见<a href="/Front2Full/manual/agent/codex/models">模型与推理</a></td></tr><tr><td><code>/plan</code></td><td>切换到计划模式</td><td>可选，作为首条规划请求</td><td><code>Shift+Tab</code> 也可以切换协作模式</td></tr><tr><td><code>/goal</code></td><td>设置或查看长任务的目标</td><td><code>&lt;目标&gt;</code>，或 <code>edit</code>、<code>pause</code>、<code>resume</code>、<code>clear</code></td><td>目标上限 4000 字符；不带参数时打开目标菜单</td></tr><tr><td><code>/voice</code></td><td>开始或结束实时语音对话</td><td>可选：<code>settings</code>（选择语音音色，v0.161.0 起还可选择麦克风、扬声器与输入声道并保存在本机）、<code>mute</code>（开关麦克风）或 <code>stop</code>（结束对话）；不带参数时在开始与结束之间切换</td><td>快捷键 <code>F8</code>（静音快捷键自 v0.163.0 起为 <code>F9</code>）。v0.164.0 起 <code>realtime_conversation</code> 特性开关退役，在附带语音运行时的平台（macOS、Linux、Windows 发布包）上常驻可用；旁支对话中不可用；CLI 文档未列出</td></tr></tbody></table><p><code>/personality</code> 已在 v0.156.0 移除（官方 CLI 文档仍列着它）：<code>friendly</code>、<code>pragmatic</code> 两种沟通风格已经退役，配置项 <code>personality</code> 只剩 <code>none</code> 还有作用，见<a href="/Front2Full/manual/agent/codex/models">模型与推理</a>。</p><h2 id="权限与沙箱" tabindex="-1">权限与沙箱 <a class="header-anchor" href="#权限与沙箱" aria-label="Permalink to &quot;权限与沙箱&quot;">​</a></h2><table tabindex="0"><thead><tr><th>命令</th><th>作用</th><th>参数</th><th>备注</th></tr></thead><tbody><tr><td><code>/permissions</code></td><td>选择 Codex 无需询问即可执行的操作（如 Auto、Read Only 预设）</td><td>可选，行内直接指定权限预设或命名权限档案（v0.164.0 起）</td><td>配置了命名权限配置档时也会列出</td></tr><tr><td><code>/approve</code></td><td>对近期一次被自动审查拒绝的操作批准重试一次</td><td></td><td>配合自动审查（Auto-review）使用</td></tr><tr><td><code>/setup-default-sandbox</code></td><td>设置提权版 Windows 沙箱</td><td></td><td>仅 Windows，且正在使用降级的受限令牌沙箱时出现</td></tr></tbody></table><p>原来仅限原生 Windows、让沙箱额外读取一个目录的 <code>/sandbox-add-read-dir</code> 已在 v0.155.0 移除，官方 CLI 参考目前仍列着它。沙箱与审批的完整说明见 <a href="/Front2Full/manual/agent/codex/sandbox-approvals">沙箱、审批与安全</a>。</p><h2 id="会话" tabindex="-1">会话 <a class="header-anchor" href="#会话" aria-label="Permalink to &quot;会话&quot;">​</a></h2><table tabindex="0"><thead><tr><th>命令</th><th>作用</th><th>参数</th><th>备注</th></tr></thead><tbody><tr><td><code>/new</code></td><td>在同一个 CLI 进程里开始新对话</td><td>可选，新对话名称</td><td>不清屏；在本地 Git 仓库里会先询问在当前检出还是新 worktree 中运行（v0.164.0 起 worktrees 常驻可用）</td></tr><tr><td><code>/clear</code></td><td>清屏并开始新对话</td><td>可选，新对话名称</td><td><code>Ctrl+L</code> 只清屏、不换对话（v0.167.0 起清屏后仍可通过 <code>Ctrl+T</code> 查看此前消息）</td></tr><tr><td><code>/resume</code></td><td>恢复一个已保存的会话</td><td>可选，会话 ID 或名称；省略则打开选择器</td><td></td></tr><tr><td><code>/fork</code></td><td>把当前对话复制为新对话（新 ID），原记录不变</td><td>可选，新对话名称</td><td>在本地 Git 仓库里同样先询问放在哪个检出；派生其他已保存会话用 <code>codex fork</code></td></tr><tr><td><code>/rename</code></td><td>重命名当前对话</td><td>可选，新名称；省略则弹出输入框</td><td></td></tr><tr><td><code>/archive</code></td><td>归档当前会话</td><td></td><td>需确认；v0.162.0 起允许在轮次运行期间执行；用 <code>codex unarchive</code> 恢复。使用内嵌服务时归档后退出；连接本机守护进程或远程 app server 时回到代理指挥中心</td></tr><tr><td><code>/delete</code></td><td>永久删除当前会话</td><td></td><td>需确认；派生的子代理线程一并删除。使用内嵌服务时删除后退出；v0.156.0 起，连接本机守护进程或远程 app server 时回到代理总览</td></tr><tr><td><code>/compact</code></td><td>总结对话以释放上下文</td><td></td><td></td></tr><tr><td><code>/recap</code></td><td>立即生成当前对话的摘要</td><td></td><td>CLI 文档未列出</td></tr><tr><td><code>/side</code>、<code>/btw</code></td><td>在临时分叉中开一个旁支对话，不影响主对话记录</td><td>可选，直接跟问题</td><td><code>Ctrl+/</code> 切换旁支对话，<code>Ctrl+C</code> 返回主线程；v0.163.0 起切换会话后仍可用 <code>/side</code> 回到已有的旁支对话</td></tr><tr><td><code>/export</code></td><td>把对话导出为 Markdown</td><td>可选，输出文件路径；省略则弹出导出选项</td><td>CLI 文档未列出</td></tr><tr><td><code>/copy</code></td><td>复制近期一条已完成的回复，或按块浏览并复制对话内容（v0.162.0 起）</td><td></td><td>快捷键 <code>Ctrl+O</code></td></tr><tr><td><code>/worktree</code></td><td>在新的 Git worktree 中开始或继续对话</td><td></td><td>v0.164.0 起 <code>worktrees</code> 特性开关退役，常驻可用；CLI 文档未列出</td></tr><tr><td><code>/cd</code></td><td>切换当前工作目录</td><td>可选，路径；省略时为 <code>~</code></td><td>CLI 文档未列出</td></tr><tr><td><code>/pwd</code></td><td>显示当前工作目录</td><td></td><td>别名 <code>/cwd</code>；CLI 文档未列出</td></tr><tr><td><code>/app</code></td><td>在 ChatGPT 桌面应用中继续当前会话</td><td></td><td>仅 macOS、Windows</td></tr><tr><td><code>/quit</code>、<code>/exit</code></td><td>退出 Codex</td><td></td><td></td></tr></tbody></table><p>会话的存储位置与命令行管理见 <a href="/Front2Full/manual/agent/codex/sessions">会话管理</a>。</p><h2 id="代码与上下文" tabindex="-1">代码与上下文 <a class="header-anchor" href="#代码与上下文" aria-label="Permalink to &quot;代码与上下文&quot;">​</a></h2><table tabindex="0"><thead><tr><th>命令</th><th>作用</th><th>参数</th><th>备注</th></tr></thead><tbody><tr><td><code>/review</code></td><td>审查当前改动并找出问题</td><td>可选，自定义审查说明；省略则打开预设菜单</td><td>见 <a href="/Front2Full/manual/agent/codex/review">代码审查</a></td></tr><tr><td><code>/diff</code></td><td>显示 git diff，包括未跟踪的文件</td><td></td><td></td></tr><tr><td><code>/mention</code></td><td>插入 <code>@</code> 并打开文件搜索</td><td></td><td>等同直接输入 <code>@</code></td></tr><tr><td><code>/init</code></td><td>让 Codex 在当前目录生成 <code>AGENTS.md</code></td><td></td><td>见 <a href="/Front2Full/manual/agent/codex/agents-md">AGENTS.md 项目指令</a></td></tr><tr><td><code>/ide</code></td><td>把 IDE 的当前选区、打开的文件等上下文带入对话</td><td>可选，<code>on</code>、<code>off</code> 或 <code>status</code></td><td></td></tr><tr><td><code>/status</code></td><td>显示会话配置（模型、审批策略、可写目录、当前选中的 ChatGPT 工作区）与 token 用量</td><td></td><td>连接本机守护进程时 Server 一行显示 Local background server；v0.166.0 起显示选中的 ChatGPT 工作区</td></tr><tr><td><code>/usage</code></td><td>查看账号用量分析，或使用一次额度重置</td><td>可选，<code>daily</code>、<code>weekly</code> 或 <code>cumulative</code>，直接打开对应的 token 活动视图</td><td>需用 ChatGPT 账号登录。v0.156.0 起菜单里的 View analytics 打开全屏的用量分析面板，分概览、用量、消息、插件、技能、对话等标签页</td></tr><tr><td><code>/debug-config</code></td><td>显示配置层顺序与 requirements 来源，排查配置为何不生效</td><td></td><td>不在弹出菜单中显示，但可以直接输入</td></tr><tr><td><code>/warnings</code></td><td>查看保留下来的警告与诊断详情（启动、运行时、MCP、弃用提示等），可逐条复制</td><td></td><td>v0.156.0 新增，快捷键 <code>F2</code>，底部状态栏显示去重后的警告数；v0.166.0 起支持文本选择与鼠标滚轮滚动；CLI 文档未列出</td></tr></tbody></table><h2 id="扩展与集成" tabindex="-1">扩展与集成 <a class="header-anchor" href="#扩展与集成" aria-label="Permalink to &quot;扩展与集成&quot;">​</a></h2><table tabindex="0"><thead><tr><th>命令</th><th>作用</th><th>参数</th><th>备注</th></tr></thead><tbody><tr><td><code>/mcp</code></td><td>列出已配置的 MCP 工具，或在会话中登录 MCP 服务器</td><td>可选，<code>verbose</code> 显示服务器详情，或 <code>login &lt;name&gt;</code> 登录指定服务器（v0.161.0 起）</td><td>见 <a href="/Front2Full/manual/agent/codex/mcp">MCP 集成</a></td></tr><tr><td><code>/skills</code></td><td>选择一个技能用于接下来的请求</td><td></td><td>也可以输入 <code>$</code> 提及技能，见 <a href="/Front2Full/manual/agent/codex/skills">Skills 技能</a></td></tr><tr><td><code>/plugins</code></td><td>浏览已安装和可发现的插件</td><td></td><td>在已安装插件上按 <code>Space</code> 启用或停用</td></tr><tr><td><code>/apps</code></td><td>管理应用（连接器），选中后以 <code>$app-slug</code> 插入输入框</td><td></td><td>需 ChatGPT 登录；不在弹出菜单中显示</td></tr><tr><td><code>/hooks</code></td><td>查看生命周期 hooks，信任、停用或重新启用非托管 hooks</td><td></td><td>见 <a href="/Front2Full/manual/agent/codex/hooks">Hooks</a></td></tr><tr><td><code>/memories</code></td><td>配置是否使用、生成记忆</td><td></td><td></td></tr><tr><td><code>/import</code></td><td>从 Claude Code 或 Cursor 导入配置、项目和近期对话</td><td></td><td>v0.157.0 起远程会话与连接本机守护进程的会话也能用</td></tr></tbody></table><h2 id="多代理与后台终端" tabindex="-1">多代理与后台终端 <a class="header-anchor" href="#多代理与后台终端" aria-label="Permalink to &quot;多代理与后台终端&quot;">​</a></h2><table tabindex="0"><thead><tr><th>命令</th><th>作用</th><th>参数</th><th>备注</th></tr></thead><tbody><tr><td><code>/agents</code></td><td>打开代理指挥中心（agent command center），查看、筛选并切换 agent 会话</td><td></td><td>输入框为空按 <code>←</code> 也能打开；v0.167.0 起内嵌会话（<code>--no-daemon</code>）中同样可用，且支持按 <code>f</code> 分叉（v0.161.0）、按 <code>p</code> 置顶（v0.162.0）、按目录分组（v0.165.0）与未读结果标记（v0.167.0）；见<a href="/Front2Full/manual/agent/codex/subagents">子代理</a></td></tr><tr><td><code>/daemon</code></td><td>管理本机的后台服务（app-server 守护进程）：显示正在运行的版本，可选择重启服务（v0.163.0 起）、安装稳定版，或改用当前 CLI 的安装包并固定版本</td><td></td><td>v0.156.0 新增；重启服务会提示可能中断的工作并在重启后自动重连；执行更新时 Codex 退出并在当前终端更新；连接远程 app server 时不可用。见 <a href="/Front2Full/manual/agent/codex/sdk-app-server">SDK 与 App Server</a>；CLI 文档未列出</td></tr><tr><td><code>/subagents</code></td><td>在本会话的子代理线程之间切换</td><td></td><td>见 <a href="/Front2Full/manual/agent/codex/subagents">子代理</a></td></tr><tr><td><code>/ps</code></td><td>列出后台终端及其近期几行输出</td><td></td><td>使用 <code>unified_exec</code> 时才会有后台终端；v0.158.0 起多行命令的预览不再只显示首行，换行显示为 <code>↵</code>，整条预览上限 80 个字符</td></tr><tr><td><code>/stop</code></td><td>停止本会话的所有后台终端</td><td></td><td>别名 <code>/clean</code></td></tr></tbody></table><h2 id="界面、账户与其他" tabindex="-1">界面、账户与其他 <a class="header-anchor" href="#界面、账户与其他" aria-label="Permalink to &quot;界面、账户与其他&quot;">​</a></h2><table tabindex="0"><thead><tr><th>命令</th><th>作用</th><th>参数</th><th>备注</th></tr></thead><tbody><tr><td><code>/config</code></td><td>打开交互式配置面板，按分类搜索并修改 Codex 偏好设置</td><td></td><td>v0.163.0 新增；可热更新的设置立即生效，需要重启的设置会在界面中标明</td></tr><tr><td><code>/keymap</code></td><td>查看并重映射快捷键，保存到 <code>tui.keymap</code></td><td>可选，<code>debug</code> 打开按键调试视图</td><td>v0.163.0 起支持配置前导键（Leader Key，默认 <code>Ctrl+X</code>）；v0.164.0 起支持绑定 <code>Command</code> / <code>Super</code> 修饰键</td></tr><tr><td><code>/vim</code></td><td>开关输入框的 Vim 模式</td><td></td><td>默认开启可设 <code>tui.vim_mode_default = true</code></td></tr><tr><td><code>/raw</code></td><td>开关原始回滚模式，方便在终端里选中复制</td><td>可选，<code>on</code> 或 <code>off</code></td><td>快捷键 <code>Alt+R</code>；默认值用 <code>tui.raw_output_mode</code></td></tr><tr><td><code>/tui</code></td><td>选择下次启动时的界面模式：Fullscreen（全屏对话记录）或 Scrollback（使用终端自己的回滚记录）</td><td></td><td>v0.156.0 新增，需确认，保存为 <code>tui.fullscreen_transcript</code>，重启后生效；<code>--no-alt-screen</code> 等启动参数仍然优先；CLI 文档未列出</td></tr><tr><td><code>/theme</code></td><td>选择语法高亮主题，保存到 <code>tui.theme</code></td><td></td><td>v0.156.0 起新增 <code>ada</code>、<code>babbage</code>、<code>curie</code>、<code>cushman</code>、<code>dali</code>、<code>davinci</code> 六个内置主题，界面的强调色也跟随主题；自定义 <code>.tmTheme</code> 放在 <code>$CODEX_HOME/themes</code></td></tr><tr><td><code>/statusline</code></td><td>配置底部状态栏显示哪些项，保存到 <code>tui.status_line</code></td><td>可选，行内直接指定状态栏项或会话级覆盖（v0.164.0 起）</td><td>v0.166.0 起新增 <code>profile</code> 与 <code>provider</code> 状态栏项</td></tr><tr><td><code>/title</code></td><td>配置终端标题显示哪些项，保存到 <code>tui.terminal_title</code></td><td>可选，行内直接指定标题栏项或会话级覆盖（v0.164.0 起）</td><td></td></tr><tr><td><code>/pets</code></td><td>选择或隐藏终端宠物</td><td>可选，宠物 ID，或 <code>off</code> 隐藏</td><td>别名 <code>/pet</code></td></tr><tr><td><code>/experimental</code></td><td>开关实验功能（如网络代理、系统代理、运行时防止休眠等）</td><td></td><td>保存到配置，部分需重启生效；v0.167.0 新增“System proxy”（<code>respect_system_proxy</code>）</td></tr><tr><td><code>/logout</code></td><td>退出登录，清除本地凭据</td><td></td><td></td></tr><tr><td><code>/feedback</code></td><td>把日志与诊断信息发送给维护者</td><td></td><td>先选反馈类别，再决定是否上传日志；v0.158.0 起，同意上传日志时还会附上 TUI 客户端近期 1 MiB 的日志（<code>client-logs.txt</code>）。诊断日志写不进本地数据库时，Codex 会发出一次警告，提醒退出前用 <code>/feedback</code> 附带日志上传，或运行 <code>codex doctor</code></td></tr></tbody></table><p>此外还有只在开发构建中出现的 <code>/rollout</code>（打印会话记录文件路径）和 <code>/test-approval</code>，以及源码中标注“请勿使用”的 <code>/debug-m-drop</code>、<code>/debug-m-update</code>。</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p><strong>哪些情况下命令不可用：</strong></p><ul><li><strong>任务进行中</strong>：<code>/new</code>、<code>/clear</code>、<code>/delete</code>、<code>/fork</code>、<code>/worktree</code>、<code>/init</code>、<code>/compact</code>、<code>/recap</code>、<code>/export</code>、<code>/review</code>、<code>/plan</code>、<code>/cd</code>、<code>/import</code>、<code>/memories</code>、<code>/config</code>、<code>/experimental</code>、<code>/keymap</code>、<code>/tui</code>、<code>/vim</code>、<code>/theme</code>、<code>/pets</code>、<code>/logout</code> 以及 Windows 的 <code>/setup-default-sandbox</code> 会提示当前不可用，其余命令（包括 v0.162.0 起放开的 <code>/archive</code>、<code>/resume</code> 以及 <code>/presets</code>、<code>/daybreak</code> 等）随时可用。v0.156.0 起，MCP 服务器仍在启动时也能使用 <code>/review</code>。</li><li><strong>旁支对话中</strong>：只能用 <code>/ide</code>、<code>/agents</code>、<code>/copy</code>、<code>/export</code>、<code>/raw</code>、<code>/diff</code>、<code>/mention</code>、<code>/status</code>、<code>/daemon</code>、<code>/warnings</code>、<code>/pwd</code>、<code>/usage</code>；代码审查进行中不能开旁支对话。</li><li><strong>按功能开关显示</strong>：<code>/goal</code>、<code>/plugins</code>、<code>/daybreak</code> 默认可用，关闭对应的功能开关（<code>goals</code>、<code>plugins</code>、<code>cli_daybreak</code>）后隐藏；<code>/worktree</code> 与 <code>/voice</code> 的功能开关已在 v0.164.0 退役（<code>/voice</code> 只在附带语音运行时的安装包里出现）。</li></ul></div><h2 id="快捷键与输入技巧" tabindex="-1">快捷键与输入技巧 <a class="header-anchor" href="#快捷键与输入技巧" aria-label="Permalink to &quot;快捷键与输入技巧&quot;">​</a></h2><table tabindex="0"><thead><tr><th>按键或输入</th><th>作用</th></tr></thead><tbody><tr><td><code>/</code></td><td>打开斜杠命令菜单（仅在消息开头）</td></tr><tr><td><code>@</code></td><td>在工作区中搜索文件，并把路径插入输入框</td></tr><tr><td>行首 <code>!</code></td><td>把这一行当作本地 shell 命令直接执行：不经审批、不进沙箱（相当于完全访问），也不走会话的网络代理；v0.167.0 起删字后露出句首 <code>!</code> 时保持在普通对话草稿模式</td></tr><tr><td><code>$</code></td><td>提及技能或应用，例如 <code>$skill-creator</code></td></tr><tr><td><code>Ctrl+V</code>、<code>Shift+Insert</code>、<code>Ctrl+Alt+V</code></td><td>粘贴剪贴板中的文本或图片（Windows 上 v0.163.0 起 <code>Ctrl+V</code> 与 <code>Shift+Insert</code> 同时支持文本与图片）；直接粘贴图片文件路径也会变成图片附件，v0.167.0 起在支持图形协议的终端上编写时可直接预览本地图片附件</td></tr><tr><td><code>Enter</code></td><td>发送；Codex 正在工作时发送，会立即打断当前回复或活跃的 Code Mode 单元并注入新指令（<code>instant_interrupt</code> 自 v0.163.0 起默认开启）</td></tr><tr><td><code>Tab</code></td><td>Codex 正在工作时，把消息、斜杠命令或 shell 命令排到下一轮</td></tr><tr><td><code>Ctrl+J</code></td><td>插入换行（终端支持时也可以用 <code>Shift+Enter</code>、<code>Alt+Enter</code>）</td></tr><tr><td><code>Esc</code></td><td>Codex 正在工作时中断当前这一轮</td></tr><tr><td>输入框为空时按两次 <code>Esc</code></td><td>浏览之前的提示词：<code>←</code>、<code>→</code> 选择，<code>Enter</code> 把当前会话回退到所选提示词之前，并把它放回输入框重新编辑。v0.156.0 起在原会话中回退，不再分叉出新会话；已经发生的文件改动不会撤销</td></tr><tr><td><code>Up</code>、<code>Down</code></td><td>翻阅草稿历史</td></tr><tr><td><code>Ctrl+R</code>、<code>Ctrl+S</code></td><td>向前、向后搜索提示历史；<code>Enter</code> 采用，<code>Esc</code> 取消</td></tr><tr><td><code>Ctrl+G</code></td><td>用 <code>VISUAL</code>（未设置时用 <code>EDITOR</code>）指定的编辑器编写长提示词，保存并关闭后回到输入框</td></tr><tr><td><code>Ctrl+O</code></td><td>复制近期一条已完成的回复</td></tr><tr><td><code>Ctrl+T</code></td><td>打开完整的对话记录视图；浏览之前的提示词时用来展开或收起详情</td></tr><tr><td><code>Ctrl+L</code></td><td>清屏，保留当前对话（v0.167.0 起清屏后仍可通过 <code>Ctrl+T</code> 查看此前消息）</td></tr><tr><td><code>Alt+R</code></td><td>开关原始回滚模式</td></tr><tr><td><code>F8</code></td><td>开始或结束语音对话（v0.156.0 起，对应 <code>tui.keymap.chat.toggle_voice</code>）</td></tr><tr><td><code>F9</code></td><td>语音对话进行中开关麦克风静音（v0.163.0 起由 <code>Ctrl+X</code> 移至 <code>F9</code>）</td></tr><tr><td><code>Ctrl+X</code></td><td>前导键（Leader Key，v0.163.0 起默认绑定）：按下后展开快捷键提示，保持打开直至选择或取消</td></tr><tr><td><code>F2</code></td><td>打开警告查看器，同 <code>/warnings</code>（v0.156.0 起）</td></tr><tr><td><code>F3</code>、<code>F4</code></td><td>在对话记录中查找；聚焦某组工具活动查看详情（v0.156.0 起，见下文“全屏对话记录”）</td></tr><tr><td><code>Ctrl+/</code></td><td>切换旁支对话</td></tr><tr><td><code>Shift+Tab</code></td><td>在协作模式（如计划模式）之间切换</td></tr><tr><td><code>Alt+,</code>、<code>Alt+.</code></td><td>在当前模型支持的档位间降低、提高推理强度，只对当前会话生效（也可以用 <code>Shift+Down</code>、<code>Shift+Up</code>）。v0.158.0 起可以一直调到 <code>max</code>，<code>ultra</code> 仍要在 <code>/model</code> 选中模型后的 More reasoning… 里选择</td></tr><tr><td><code>Shift+Left</code></td><td>编辑已排队的消息（也可以用 <code>Alt+Up</code>）。v0.158.0 起不再按终端挑选，界面提示统一显示 <code>Shift+Left</code>（此前多数终端里提示的是 <code>Alt+Up</code>）</td></tr><tr><td><code>Alt+Left</code>、<code>Alt+Right</code></td><td>切换到上一个、下一个 agent</td></tr><tr><td>输入框为空时按 <code>←</code></td><td>打开代理总览（连接本机守护进程时）。v0.158.0 起，对话正在另一个应用中打开、这里只能只读查看时，除了 <code>Esc</code> 也可以按 <code>←</code> 回到代理总览</td></tr><tr><td>空输入框中按 <code>?</code></td><td>显示快捷键提示</td></tr><tr><td><code>Ctrl+C</code></td><td>中断当前任务；空闲时再按一次退出（<code>Ctrl+D</code> 同样可以退出）</td></tr></tbody></table><p>除 <code>/</code>、<code>@</code>、<code>!</code>、<code>$</code>、<code>Esc</code>（回溯）、<code>Ctrl+C</code>、<code>Ctrl+D</code>、<code>Ctrl+V</code>、<code>Ctrl+Alt+V</code>、<code>Shift+Tab</code>、<code>Alt+Left</code>、<code>Alt+Right</code>、<code>F2</code> 与空输入框里的 <code>←</code>（把 <code>editor.move_left</code> 改成不含 <code>left</code> 后它就不再打开代理总览）这些固定按键外，上表中的快捷键都可以用 <code>/keymap</code> 或 <code>config.toml</code> 中的 <code>tui.keymap</code> 重新绑定。键名写作 <code>ctrl-a</code>、<code>shift-enter</code>、<code>page-down</code> 这样的形式；针对具体场景的绑定会覆盖 <code>tui.keymap.global</code>，绑定为空列表表示解绑。v0.156.0 新增的默认键（<code>F2</code>、<code>F3</code>、<code>F4</code>、<code>F8</code>）如果已经被你绑定给了别的操作，会自动让位，不会冲突。</p><h2 id="全屏对话记录" tabindex="-1">全屏对话记录 <a class="header-anchor" href="#全屏对话记录" aria-label="Permalink to &quot;全屏对话记录&quot;">​</a></h2><p>v0.157.0 起，交互界面默认使用“全屏对话记录”（<code>tui.fullscreen_transcript = true</code>，v0.156.0 可以用 <code>/tui</code> 手动开启）：对话记录画在终端的备用屏幕里，滚动、选择与搜索都由 Codex 自己处理，不再依赖终端的回滚记录。</p><table tabindex="0"><thead><tr><th>操作</th><th>作用</th></tr></thead><tbody><tr><td><code>PgUp</code>、<code>PgDn</code>、鼠标滚轮</td><td>滚动对话记录（v0.162.0 起可用 <code>tui.mouse_scroll_speed</code> 调节滚轮速度倍率，默认 <code>1.0</code>）</td></tr><tr><td><code>Ctrl+Home</code>、<code>Ctrl+End</code></td><td>跳到开头、回到底部（也可以用 <code>Alt+Shift+,</code>、<code>Alt+Shift+.</code>）</td></tr><tr><td>鼠标拖动、双击、三击</td><td>选择文本，双击选中整个词，三击选中整行；按住 <code>Shift</code> 单击可以扩展已有的选区（v0.157.0 起）</td></tr><tr><td>松开鼠标</td><td>v0.158.0 起，用鼠标选中文字后一松开就自动复制，选区保留，由 <code>tui.copy_on_select</code> 控制（v0.164.0 起输入框文本同样适用，见下文）</td></tr><tr><td><code>Ctrl+Space</code></td><td>用键盘开始选择，再用方向键或按词、行、页移动选区并支持内置搜索与自定义快捷键（v0.166.0 增强）</td></tr><tr><td>有选区时按 <code>Ctrl+C</code>、<code>Ctrl+Insert</code>、<code>Enter</code></td><td>复制选中的文本（<code>Ctrl+Shift+C</code>、<code>Ctrl+Insert</code>（v0.162.0 起）以及终端转发过来的 <code>Cmd+C</code> 也可以；复制时同时保留纯文本与富文本 HTML），<code>Enter</code> 复制后回到底部；<code>Esc</code> 取消选择</td></tr><tr><td>右键</td><td>有选区时复制选中的文本（在输入框里同样可用）；v0.158.0 起，没有选区时把剪贴板里的文本粘贴到输入框，由 <code>tui.right_click_paste</code> 控制</td></tr><tr><td>单击链接或图片路径</td><td>打开链接（Markdown 链接和裸 URL 均可；v0.162.0 起审批标题、提问、MCP 提示、警告与横幅中的跨行 URL 也可点击；v0.167.0 起对话记录里查看过的本地图片路径也可点击打开）</td></tr><tr><td><code>F3</code></td><td>在整个对话记录中查找，不区分大小写，需要时会加载更早的历史；对话记录视图里也可以按 <code>/</code></td></tr><tr><td><code>F4</code></td><td>聚焦某组工具活动，查看它的详细内容</td></tr></tbody></table><p>v0.158.0 起，从对话记录里复制选区会保留 Markdown 格式：粗体、斜体、行内代码、链接、标题、列表、引用和表格都按 Markdown 写出，只选中代码等原样内容时仍按原文复制；想要整条回复的 Markdown 原文，用 <code>/copy</code> 或 <code>Ctrl+O</code>。松开即复制与右键粘贴各有一个配置：</p><ul><li><code>tui.copy_on_select</code>：<code>auto</code>（默认）、<code>always</code> 或 <code>never</code>，对 <code>Ctrl+T</code> 打开的对话记录视图、恢复/派生会话时的预览以及底部输入框文本（v0.164.0 起）同样生效。<code>auto</code> 下大多数终端松开即复制，在 tmux、Zellij 里也是；只有直接在 Ghostty 1.2 及以上、macOS 上的 Kitty、Windows Terminal、Windows 上的 VS Code 中运行时不自动复制，因为这些终端的复制快捷键在终端自己没有选区时会转发给 Codex，直接按它即可。<code>never</code> 表示只用上表的按键或右键复制。另有 <code>tui.copy_on_select_clear_selection = true</code> 可在复制只读对话记录后自动取消选区。</li><li><code>tui.right_click_paste</code>：<code>auto</code>（默认）、<code>on</code> 或 <code>off</code>。<code>auto</code> 在 Windows、Linux（含 WSL）上启用，<code>on</code> 另外在 macOS 上启用；两者在 SSH 会话和 VS Code 的终端里都不读取剪贴板，也只在输入框可以编辑、没有选区、没在查找时才粘贴。<code>off</code> 则不做这种粘贴，右键粘贴留给终端自己处理。</li></ul><p>在支持 Kitty 或 Sixel 图形协议的终端上，v0.164.0 起全屏对话记录可直接内嵌预览模型查看或生成的图片；v0.167.0 起，当审批提示打开时，还可以直接在对话记录中展开补丁详情。新会话标题栏在 v0.161.0 起移除了随机问候语，保持紧凑样式；全屏模式下空白处的花朵动画点一下会重播（受 <code>tui.animations</code> 与 <code>tui.effects.welcome</code> 控制）。全屏模式不显示启动提示，输入框上方不再轮换显示使用提示（那里只留给额度提醒），改为：一轮运行超过 30 秒时，工作状态指示下方会出现一条随机提示；从第三轮起，部分成功完成的回复后面也会出现一条（每次启动上限两条）。提示里的快捷键按你当前的绑定显示，也不会被选中或查找到；<code>tui.show_tooltips = false</code> 可以关掉。</p><p>想换回终端自己的回滚记录（例如习惯用终端的搜索与复制），在 <code>/tui</code> 里选 Scrollback 后重启，或在配置里写 <code>tui.fullscreen_transcript = false</code>。不使用备用屏幕时（<code>--no-alt-screen</code> 或 <code>tui.alternate_screen = &quot;never&quot;</code>）也是回滚记录模式；<code>tui.alternate_screen = &quot;auto&quot;</code> 时，通过 SSH 使用 macOS 自带的 Terminal.app 会自动改用回滚记录。v0.157.0 起，tmux 中设置了 <code>mouse off</code> 时，Codex 不再捕获鼠标。</p>',33)])])}const m=t(r,[["render",a]]);export{p as __pageData,m as default};
